// Package prompts embeds prompts.json, generated by `task services:prompts` (python -m zj_eval.service_prompts)
// from the same builders as the benchmark, so production sends the measured prompt bytes.
package prompts

import (
	_ "embed"
	"encoding/json"
	"fmt"
)

//go:embed prompts.json
var raw []byte

// Message is one OpenAI chat message.
type Message struct {
	Role    string `json:"role"`
	Content string `json:"content"`
}

// Chat is a system prompt, optional few-shot messages and the JSON schema the answer is constrained to.
type Chat struct {
	System    string          `json:"system"`
	Shots     []Message       `json:"shots"`
	Schema    json.RawMessage `json:"schema"`
	MaxTokens int             `json:"max_tokens"`
}

// Messages builds system + shots + one user turn.
func (c Chat) Messages(user string) []Message {
	m := make([]Message, 0, len(c.Shots)+2)
	m = append(m, Message{Role: "system", Content: c.System})
	m = append(m, c.Shots...)
	return append(m, Message{Role: "user", Content: user})
}

// Set holds every prompt the services send.
type Set struct {
	Router Chat `json:"router"`
	Answer struct {
		Chat
		MaxRows int `json:"max_rows"`
	} `json:"answer"`
	Label struct {
		Chat
		Sample int   `json:"sample"`
		Seed   int64 `json:"seed"`
	} `json:"label"`
	Extract Chat `json:"extract"`
	Search  struct {
		K    int `json:"k"`
		RRFK int `json:"rrf_k"`
	} `json:"search"`
	Catalog   map[string][]string `json:"catalog"`
	MaxTokens int                 `json:"max_tokens"`
}

// InCatalog reports whether v is a canonical value of the catalog key (komponente, schadensart, werk, …).
func (s *Set) InCatalog(key, v string) bool {
	for _, c := range s.Catalog[key] {
		if c == v {
			return true
		}
	}
	return false
}

// Classes are the schadensart labels in schema order.
func (s *Set) Classes() []string { return s.Catalog["schadensart"] }

// Load parses the embedded file.
func Load() (*Set, error) {
	var s Set
	if err := json.Unmarshal(raw, &s); err != nil {
		return nil, fmt.Errorf("prompts.json: %w", err)
	}
	if s.Router.System == "" || s.Extract.System == "" || len(s.Classes()) == 0 || s.Search.K <= 0 {
		return nil, fmt.Errorf("prompts.json: incomplete (regenerate with `task services:prompts`)")
	}
	if s.Router.MaxTokens == 0 {
		s.Router.MaxTokens = s.MaxTokens
	}
	if s.Answer.MaxTokens == 0 {
		s.Answer.MaxTokens = s.MaxTokens
	}
	if s.Label.MaxTokens == 0 {
		s.Label.MaxTokens = s.MaxTokens
	}
	return &s, nil
}
